  }
</script>

<style>
  /* Container căn giữa + fade-in */


  /* Container căn giữa + fade-in */
  .fader {
    display: flex;
    justify-content: center;
    /* bỏ margin-top đi */
    animation: fadeIn 0.8s ease-out;
  }

  @keyframes fadeIn {
    from {
      opacity: 0;
      transform: translateY(12px);
    }

    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  /* Fade-out toàn body */
  .fadeout {
    animation: fadeOutBody 1s forwards;
  }

  @keyframes fadeOutBody {
    to {
      opacity: 0;
      transform: scale(1.02);
    }
  }

  /* Nút glassmorphism gradient tím-đỏ-tím */
  .tab-btn-purple {
    width: 320px;
    /* to hơn */
    height: 65px;
    /* cao hơn */
    margin-top: 0px;
    font-size: 20px;
    /* chữ lớn hơn */
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 1px;
    color: #fff;
    border: none;
    border-radius: 12px 12px 0 0;
    cursor: pointer;
    position: relative;
    overflow: hidden;
    background: rgba(255, 255, 255, 0.12);
    backdrop-filter: blur(8px);
    border: 1px solid rgba(255, 255, 255, 0.2);
    box-shadow: none;
    /* bỏ đổ bóng */
    transition: all 0.3s ease;
  }

  /* Viền gradient động */
  .tab-btn-purple::before {
    content: "";
    position: absolute;
    top: -2px;
    left: -2px;
    right: -2px;
    bottom: -2px;
    background: linear-gradient(90deg, #7b4397, #dc2430, #7b4397);
    border-radius: 14px 14px 0 0;
    z-index: -1;
    background-size: 200% 200%;
    animation: borderMovePurple 4s linear infinite;
  }

  @keyframes borderMovePurple {
    0% {
      background-position: 0% 50%;
    }

    50% {
      background-position: 100% 50%;
    }

    100% {
      background-position: 0% 50%;
    }
  }

  /* Hover & Active effect */
  .tab-btn-purple:hover {
    transform: translateY(-3px);
    box-shadow: none;
    /* bỏ bóng khi hover */
  }

  .tab-btn-purple:active {
    transform: translateY(0);
    box-shadow: none;
    /* bỏ bóng khi click */
  }
</style>

